namespace LocalRun.Core.Resources;

internal static class Dialogue
{
    public static string Welcome => "──────────────────────────────────────────────────────────────\r\n Welcome to LocalRun — your local .NET build and deploy manager\r\n──────────────────────────────────────────────────────────────\r\n\r\nLocalRun helps you rebuild and run only what matters in your local environment.\r\nIt analyzes your repository tree, detects Git changes, and maps dependency \r\nrelationships between libraries and executables.\r\n\r\nFrom there, you can:\r\n • Build a dependency graph and save it as a config file.\r\n • Filter projects by type of change or dependency.\r\n • Repack changed libraries to your LocalNuGet cache.\r\n • Rebuild and start executables in proper dependency order.\r\n\r\nType 'help' to list all available commands.\r\n";

    public static string Help => "──────────────────────────────\r\n LocalRun Command Reference\r\n──────────────────────────────\r\n\r\nCommands:\r\n\r\n  build-config [options]\r\n      Analyze the source tree and build a dependency graph.\r\n      Produces a JSON config file that can be edited before repack.\r\n      Options:\r\n        --mode <git|all|filter>    Build mode (default: git)\r\n        --filter <names>           Comma-separated list of libs/exes to include\r\n        --root <path>              Override root search path (default: current dir)\r\n      Example:\r\n        build-config --mode git --filter CoreLib,AppHost\r\n\r\n  repack\r\n      Repack all solutions in the current config file.\r\n      Packages are created in dependency order and pushed to LocalNuGet.\r\n\r\n  run\r\n      Launch executables defined in the config file, in dependency order.\r\n\r\n  help\r\n      Print this help message.\r\n\r\n  exit\r\n      Quit LocalRun interactive mode.\r\n\r\n──────────────────────────────\r\nUsage Examples:\r\n──────────────────────────────\r\n  LocalRun> build-config --mode git\r\n  LocalRun> build-config --mode filter --filter AppHost\r\n  LocalRun> repack\r\n  LocalRun> run\r\n──────────────────────────────\r\n";

}
